<?php
declare(strict_types=1);
require_once __DIR__.'/safety_vote_result_release.php';
const SV4_CONTRACT='2026-10-08-safety-vote-phase4-r1';
const SV4_CLOSE_FINALIZATION_CONTRACT='2026-10-25-safety-vote-close-finalization-r1';
const SV4_JURY_MATRIX_CONTRACT='2026-10-25-jury-work-criteria-matrix-r1';
function sv4_num($v,float$d=0):float{return is_numeric($v)?(float)$v:$d;} function sv4_round($v):float{return round((float)$v,6);} function sv4_hash($v):string{return hash('sha256',json_encode($v,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));}
function sv4_jury_matrix(array$a,array$criteria,array$works,array$scores):array{$cells=[];$completed=[];foreach($scores as$row)$completed[(int)($row['candidateId']??$row['CandidateID']??0).':'.(int)($row['criterionId']??$row['CriterionID']??0)]=true;foreach($works as$work)foreach($criteria as$criterion)$cells[]=['workId'=>(int)$work['id'],'criterionId'=>(int)$criterion['id'],'min'=>(float)($criterion['MinScore']??$criterion['minScore']??0),'max'=>(float)($criterion['MaxScore']??$criterion['maxScore']??0),'weight'=>(float)($criterion['Weight']??$criterion['weight']??0)];$done=0;foreach($cells as$cell)if(isset($completed[$cell['workId'].':'.$cell['criterionId']]))$done++;$canonical=['assignmentId'=>(int)$a['id'],'sheetVersion'=>(int)($a['SheetVersion']??1),'stageId'=>(int)$a['StageID'],'workSource'=>$a['WorkSource']??'admin_curated','blind'=>(bool)($a['BlindMode']??false),'cells'=>$cells];return['contractVersion'=>SV4_JURY_MATRIX_CONTRACT,'workCount'=>count($works),'criteriaCount'=>count($criteria),'cellCount'=>count($cells),'completedCells'=>$done,'weightTotal'=>array_sum(array_map(function($row){return(float)($row['Weight']??$row['weight']??0);},$criteria)),'complete'=>count($cells)>0&&$done===count($cells),'blind'=>(bool)($a['BlindMode']??false),'workSource'=>$a['WorkSource']??'admin_curated','resultBinding'=>'submitted_score_rows_to_frozen_result','matrixHash'=>sv4_hash($canonical)];}
function sv4_config($r):array{$r=is_array($r)?$r:[];$m=in_array($r['method']??'', ['weighted_jury','hybrid','rank_points','allocation'],true)?$r['method']:'weighted_jury';$jw=max(0,sv4_num($r['juryWeight']??null,$m==='hybrid'?60:100));$pw=max(0,sv4_num($r['popularWeight']??null,$m==='hybrid'?40:0));$tie=in_array($r['tieBreak']??'', ['candidate_id','jury_score','popular_score'],true)?$r['tieBreak']:'candidate_id';return['method'=>$m,'juryWeight'=>$jw,'popularWeight'=>$pw,'topN'=>max(1,min(100,(int)sv4_num($r['topN']??null,1))),'threshold'=>sv4_num($r['threshold']??null,0),'minJurors'=>max(1,(int)sv4_num($r['minJurors']??null,1)),'minParticipation'=>max(0,(int)sv4_num($r['minParticipation']??null,0)),'tieBreak'=>$tie,'excludeHighLow'=>($r['excludeHighLow']??false)===true];}
function sv4_criteria($in):array{if(!is_array($in)||!$in||count($in)>50)return['ok'=>false,'errors'=>['CRITERIA_REQUIRED'],'criteria'=>[]];$seen=[];$errors=[];$out=[];foreach(array_values($in)as$i=>$x){$code=strtoupper(substr(trim((string)($x['criterionCode']??'C'.($i+1))),0,50));$min=sv4_num($x['minScore']??null,0);$max=sv4_num($x['maxScore']??null,10);$w=sv4_num($x['weight']??null,1);if(!$code||isset($seen[$code]))$errors[]='CRITERION_CODE_DUPLICATE';$seen[$code]=1;if(!trim((string)($x['title']??''))||$max<=$min||$w<=0)$errors[]='CRITERION_INVALID';$out[]=['id'=>isset($x['id'])?(int)$x['id']:null,'criterionCode'=>$code,'title'=>substr(trim((string)($x['title']??'')),0,300),'description'=>trim((string)($x['description']??''))?:null,'minScore'=>$min,'maxScore'=>$max,'weight'=>$w,'sortOrder'=>(int)($x['sortOrder']??$i+1)];}return['ok'=>!$errors,'errors'=>array_values(array_unique($errors)),'criteria'=>$out];}
function sv4_sheet(array$criteria,array$candidateIds,$scores,bool$requireComplete=true):array{$by=[];foreach($criteria as$c)$by[(int)$c['id']]=$c;$allowed=array_fill_keys(array_map('intval',$candidateIds),true);$seen=[];$errors=[];$rows=[];foreach(is_array($scores)?$scores:[]as$x){$cid=(int)($x['candidateId']??0);$kid=(int)($x['criterionId']??0);$key="$cid:$kid";$c=$by[$kid]??null;$score=isset($x['score'])&&is_numeric($x['score'])?(float)$x['score']:NAN;if(!isset($allowed[$cid])||!$c||isset($seen[$key])||is_nan($score)||$score<(float)$c['minScore']||$score>(float)$c['maxScore']){$errors[]='SCORE_INVALID';continue;}$seen[$key]=1;$rows[]=['candidateId'=>$cid,'criterionId'=>$kid,'score'=>$score,'comment'=>substr(trim((string)($x['comment']??'')),0,1000)?:null];}if($requireComplete)foreach($allowed as$cid=>$_)foreach($criteria as$c)if(!isset($seen[$cid.':'.(int)$c['id']]))$errors[]='SCORE_MISSING';return['ok'=>!$errors,'errors'=>array_values(array_unique($errors)),'rows'=>$rows];}
function sv4_calculate(array$in):array{$cfg=sv4_config($in['config']??[]);$criteria=$in['criteria']??[];$candidateIds=array_values(array_unique(array_map('intval',$in['candidateIds']??[])));sort($candidateIds);$submitted=array_values(array_filter($in['sheets']??[],fn($s)=>($s['status']??'')==='Submitted'&&($s['conflictState']??'clear')!=='recused'));$popular=[];foreach($in['popular']??[]as$x)$popular[(int)$x['candidateId']]=sv4_num($x['value']??0);$participation=max(0,(int)sv4_num($in['participationCount']??0));$jur=[];foreach($submitted as$s)$jur[(string)$s['jurorEmployeeId']]=1;$quorum=$participation>=$cfg['minParticipation']&&count($jur)>=$cfg['minJurors']?'met':'not_met';$rows=[];foreach($candidateIds as$cid){$norm=[];foreach($submitted as$s){$sum=0;$weights=0;foreach($s['scores']??[]as$x)if((int)$x['candidateId']===$cid){$c=null;foreach($criteria as$z)if((int)$z['id']===(int)$x['criterionId']){$c=$z;break;}if($c){$sum+=((sv4_num($x['score'])-sv4_num($c['minScore']))/(sv4_num($c['maxScore'])-sv4_num($c['minScore'])))*sv4_num($c['weight']);$weights+=sv4_num($c['weight']);}}if($weights)$norm[]=$sum/$weights*100;}sort($norm);$vals=$norm;if($cfg['excludeHighLow']&&count($vals)>=3)$vals=array_slice($vals,1,-1);$jury=$vals?array_sum($vals)/count($vals):0;$pop=$popular[$cid]??0;$total=$cfg['method']==='hybrid'?($jury*$cfg['juryWeight']+$pop*$cfg['popularWeight'])/($cfg['juryWeight']+$cfg['popularWeight']?:1):(in_array($cfg['method'],['allocation','rank_points'],true)?$pop:$jury);$rows[]=['candidateId'=>$cid,'juryScore'=>sv4_round($jury),'popularScore'=>sv4_round($pop),'totalScore'=>sv4_round($total),'judgeCount'=>count($norm)];}usort($rows,function($a,$b)use($cfg){if($a['totalScore']!==$b['totalScore'])return$b['totalScore']<=>$a['totalScore'];if($cfg['tieBreak']==='jury_score'&&$a['juryScore']!==$b['juryScore'])return$b['juryScore']<=>$a['juryScore'];if($cfg['tieBreak']==='popular_score'&&$a['popularScore']!==$b['popularScore'])return$b['popularScore']<=>$a['popularScore'];return$a['candidateId']<=>$b['candidateId'];});$tie='none';foreach($rows as$i=>&$r){$r['rank']=$i+1;$r['advanced']=$quorum==='met'&&$r['rank']<=$cfg['topN']&&$r['totalScore']>=$cfg['threshold'];if($i&&$r['totalScore']===$rows[$i-1]['totalScore'])$tie='resolved';}unset($r);$payload=['contract'=>SV4_CONTRACT,'config'=>$cfg,'quorumState'=>$quorum,'tieState'=>$tie,'participationCount'=>$participation,'submittedJurors'=>count($jur),'rows'=>$rows];return$payload+['inputHash'=>sv4_hash(['config'=>$cfg,'criteria'=>$criteria,'candidateIds'=>$candidateIds,'sheets'=>$submitted,'popular'=>$popular]),'resultHash'=>sv4_hash($payload)];}
function sv4_stages($in):array{if(!is_array($in)||!$in)return['ok'=>false,'errors'=>['STAGES_REQUIRED'],'stages'=>[]];$errors=[];$keys=[];$seq=[];$out=[];foreach(array_values($in)as$i=>$x){$key=strtoupper(substr(trim((string)($x['stageKey']??'STAGE_'.($i+1))),0,50));$n=(int)sv4_num($x['sequenceNo']??null,$i+1);if(isset($keys[$key])||isset($seq[$n])||!trim((string)($x['stageName']??'')))$errors[]='STAGE_INVALID';$keys[$key]=1;$seq[$n]=1;$out[]=['id'=>isset($x['id'])?(int)$x['id']:null,'stageKey'=>$key,'stageName'=>substr(trim((string)($x['stageName']??'')),0,160),'stageType'=>substr((string)($x['stageType']??'jury'),0,40),'sequenceNo'=>$n,'advanceRule'=>['topN'=>max(1,(int)sv4_num($x['advanceRule']['topN']??null,1)),'threshold'=>sv4_num($x['advanceRule']['threshold']??null,0),'blind'=>($x['advanceRule']['blind']??false)===true],'resultVisibility'=>(string)($x['resultVisibility']??'admin_only'),'status'=>(string)($x['status']??'Draft')];}usort($out,fn($a,$b)=>$a['sequenceNo']<=>$b['sequenceNo']);return['ok'=>!$errors,'errors'=>array_values(array_unique($errors)),'stages'=>$out];}

function sv4_finalize_closed_popular_vote(int $campaignId,string $actor='SYSTEM_SCHEDULE',string $trigger='scheduled_close'):array{
 $pdo=db();$pdo->beginTransaction();
 try{
  $campaign=db_row("SELECT c.id,c.CurrentVersionID,c.CampaignCode,c.Status,v.CampaignType,v.QuorumRuleJson,v.ResultReleasePolicy FROM SafetyVote_Campaigns c JOIN SafetyVote_CampaignVersions v ON v.id=c.CurrentVersionID WHERE c.id=? FOR UPDATE",[$campaignId]);
  if(!$campaign||$campaign['Status']!=='Closed'){$pdo->rollBack();return['status'=>'skipped','reason'=>'CAMPAIGN_NOT_CLOSED'];}
  if($campaign['CampaignType']!=='popular_vote'){$pdo->rollBack();return['status'=>'manual_required','reason'=>'GOVERNED_CAMPAIGN_TYPE'];}
  $versionId=(int)$campaign['CurrentVersionID'];
  $raw=db_rows("SELECT q.id questionId,q.QuestionCode questionCode,q.Title questionTitle,o.id optionId,o.OptionCode optionCode,o.Label optionLabel,o.IsAbstain,COUNT(DISTINCT b.id) votes FROM SafetyVote_Questions q JOIN SafetyVote_Options o ON o.QuestionID=q.id AND o.Status='Active' LEFT JOIN SafetyVote_BallotAnswers a ON a.QuestionID=q.id AND a.OptionID=o.id LEFT JOIN SafetyVote_Ballots b ON b.id=a.BallotID AND b.CampaignVersionID=? AND b.Status='Accepted' WHERE q.CampaignVersionID=? AND q.Status='Active' AND q.QuestionType IN ('single_choice','multiple_choice','yes_no_abstain') GROUP BY q.id,q.QuestionCode,q.Title,o.id,o.OptionCode,o.Label,o.IsAbstain ORDER BY q.SortOrder,q.id,o.SortOrder,o.id",[$versionId,$versionId]);
  if(!$raw){$pdo->rollBack();return['status'=>'manual_required','reason'=>'UNSUPPORTED_RESULT_INPUT'];}
  $counts=db_row("SELECT (SELECT id FROM SafetyVote_EligibilitySnapshots WHERE CampaignVersionID=? AND Status='frozen' ORDER BY SnapshotNo DESC LIMIT 1) eligibilitySnapshotId,(SELECT EligibleCount FROM SafetyVote_EligibilitySnapshots WHERE CampaignVersionID=? AND Status='frozen' ORDER BY SnapshotNo DESC LIMIT 1) eligible,(SELECT COUNT(*) FROM SafetyVote_Participation WHERE CampaignVersionID=? AND State='submitted') participation,(SELECT COUNT(*) FROM SafetyVote_Ballots WHERE CampaignVersionID=? AND Status='Accepted') accepted,(SELECT COUNT(*) FROM SafetyVote_Ballots WHERE CampaignVersionID=? AND Status='Rejected') rejected",[$versionId,$versionId,$versionId,$versionId,$versionId]);
  $groups=[];foreach($raw as$item)$groups[(int)$item['questionId']][]=$item;$rows=[];
  foreach($groups as$group){usort($group,function($a,$b){$votes=(int)$b['votes']<=>(int)$a['votes'];return$votes!==0?$votes:(int)$a['optionId']<=>(int)$b['optionId'];});$denominator=array_sum(array_map(function($item){return(int)$item['votes'];},$group));$prior=null;$rank=0;foreach($group as$index=>$item){if($denominator>0&&($prior===null||(int)$item['votes']!==$prior))$rank=$index+1;$prior=(int)$item['votes'];$item['rank']=$denominator>0?$rank:null;$item['denominator']=$denominator;$rows[]=$item;}}
  $quorum=json_decode((string)($campaign['QuorumRuleJson']??'{}'),true)?:[];$quorumState=(int)$counts['participation']>=max(0,(int)($quorum['minParticipation']??0))?'met':'not_met';$tie=false;
  foreach($groups as$questionId=>$_){$top=0;foreach($rows as$item)if((int)$item['questionId']===(int)$questionId&&(int)$item['denominator']>0&&(int)$item['rank']===1)$top++;if($top>1){$tie=true;break;}}
  $tieState=$tie?'tie':'none';$inputRows=array_map(function($item){return[(int)$item['questionId'],(int)$item['optionId'],(int)$item['votes']];},$rows);$inputHash=sv4_hash(['campaignVersionId'=>$versionId,'accepted'=>(int)$counts['accepted'],'rows'=>$inputRows]);$resultRows=array_map(function($item){return[(int)$item['questionId'],(int)$item['optionId'],(int)$item['votes'],$item['rank']];},$rows);$resultHash=sv4_hash(['contract'=>SV4_CLOSE_FINALIZATION_CONTRACT,'inputHash'=>$inputHash,'quorumState'=>$quorumState,'tieState'=>$tieState,'rows'=>$resultRows]);
  $existing=db_row('SELECT id,SnapshotNo,Status,ResultHash FROM SafetyVote_ResultSnapshots WHERE CampaignVersionID=? AND StageID IS NULL AND CalculationContract=? AND InputHash=? ORDER BY SnapshotNo DESC,id DESC LIMIT 1',[$versionId,SV4_CLOSE_FINALIZATION_CONTRACT,$inputHash]);if($existing){$pdo->commit();return['status'=>'already_finalized','snapshotId'=>(int)$existing['id'],'snapshotNo'=>(int)$existing['SnapshotNo'],'resultHash'=>$existing['ResultHash']];}
  $sequence=db_row('SELECT COALESCE(MAX(SnapshotNo),0)+1 no FROM SafetyVote_ResultSnapshots WHERE CampaignVersionID=? AND StageID IS NULL',[$versionId]);$abstain=0;foreach($rows as$item)if((int)$item['IsAbstain']===1)$abstain+=(int)$item['votes'];
  $insert=$pdo->prepare("INSERT INTO SafetyVote_ResultSnapshots(CampaignID,CampaignVersionID,StageID,SnapshotNo,CalculationContract,EligibilitySnapshotID,Status,EligibleCount,ParticipationCount,AcceptedBallotCount,RejectedBallotCount,AbstainCount,QuorumState,TieState,ReconciliationState,InputHash,ResultHash,CalculatedBy,FrozenAt,FrozenBy) VALUES(?,?,NULL,?,?,?,?,?,?,?,?,?,?,?,'balanced',?,?,?,NOW(),?)");$insert->execute([$campaignId,$versionId,(int)$sequence['no'],SV4_CLOSE_FINALIZATION_CONTRACT,$counts['eligibilitySnapshotId']?:null,'Frozen',(int)$counts['eligible'],(int)$counts['participation'],(int)$counts['accepted'],(int)$counts['rejected'],$abstain,$quorumState,$tieState,$inputHash,$resultHash,$actor,$actor]);$snapshotId=(int)$pdo->lastInsertId();
  $insertRow=$pdo->prepare("INSERT INTO SafetyVote_ResultRows(ResultSnapshotID,QuestionID,OptionID,MetricKey,RawCount,Numerator,Denominator,NumericValue,RankNo,ResultState,MetadataJson) VALUES(?,?,?,'vote_count',?,?,?,?,?,?,?)");foreach($rows as$item){$state=(int)$item['denominator']===0?'no_result':((int)$item['rank']===1?'winner':'normal');$percentage=(int)$item['denominator']>0?round((int)$item['votes']/(int)$item['denominator']*100,2):0;$insertRow->execute([$snapshotId,(int)$item['questionId'],(int)$item['optionId'],(int)$item['votes'],(int)$item['votes'],(int)$item['denominator'],(int)$item['votes'],$item['rank'],$state,json_encode(['questionCode'=>$item['questionCode'],'questionTitle'=>$item['questionTitle'],'optionCode'=>$item['optionCode'],'optionLabel'=>$item['optionLabel'],'percentage'=>$percentage],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)]);}
  $release=sv_result_release_decision(['policy'=>$campaign['ResultReleasePolicy']??'manual','campaignType'=>$campaign['CampaignType'],'snapshotStatus'=>'Frozen','reconciliationState'=>'balanced','governanceReady'=>true]);
  if($release['action']==='publish'){$pdo->prepare("UPDATE SafetyVote_ResultSnapshots SET Status='Published' WHERE id=? AND Status='Frozen'")->execute([$snapshotId]);$pdo->prepare("UPDATE SafetyVote_Campaigns SET Status='Published',PublishedAt=COALESCE(PublishedAt,NOW()),UpdatedBy=?,RowVersion=RowVersion+1 WHERE id=? AND Status='Closed'")->execute([$actor,$campaignId]);}
  $detail=$release['action']==='publish'?'Closed campaign result calculated and published by policy':'Closed campaign result calculated and frozen automatically';
  $pdo->prepare("INSERT INTO SafetyVote_AuditLogs(CampaignID,CampaignVersionID,ActorEmployeeID,ActorRole,Action,TargetType,TargetID,StatusCode,BoundedDetail,MetadataJson) VALUES(?,?,?,'SYSTEM','SAFETY_VOTE_RESULT_AUTO_FINALIZE','SafetyVote_ResultSnapshot',?,200,?,?)")->execute([$campaignId,$versionId,$actor,(string)$snapshotId,$detail,json_encode(['trigger'=>$trigger,'contract'=>SV4_CLOSE_FINALIZATION_CONTRACT,'releaseContract'=>SAFETY_VOTE_RESULT_RELEASE_CONTRACT,'releasePolicy'=>$release['policy'],'releaseAction'=>$release['action'],'acceptedBallots'=>(int)$counts['accepted'],'noResult'=>(int)$counts['accepted']===0,'resultHash'=>$resultHash],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)]);
  $pdo->commit();return['status'=>$release['action']==='publish'?'published':'finalized','snapshotStatus'=>$release['action']==='publish'?'Published':'Frozen','releasePolicy'=>$release['policy'],'releaseReason'=>$release['reason'],'snapshotId'=>$snapshotId,'snapshotNo'=>(int)$sequence['no'],'resultHash'=>$resultHash,'quorumState'=>$quorumState,'tieState'=>$tieState,'noResult'=>(int)$counts['accepted']===0];
 }catch(Throwable$error){if($pdo->inTransaction())$pdo->rollBack();throw$error;}
}
